            add(conn,2-n,('SA2',p),[(p,-w_sa)])
        if user_extra: user_extra(L6,ro,iown,iopp,iL,add)
    return build_g(w_sa=0.0, extra=extra, **kw)
def pb2(**kw):
    Ws,bs,W7,b7=build_g2(**kw)
    used=np.abs(W7).sum(1)>0
    idx=np.where(used)[0]; assert len(idx)<=512, len(idx)
    W6=np.zeros((Ws[5].shape[0],512),np.float32); b6=np.zeros(512,np.float32); W7n=np.zeros((512,82),np.float32)
    W6[:,:len(idx)]=Ws[5][:,idx]; b6[:len(idx)]=bs[5][idx]; W7n[:len(idx)]=W7[idx]
    Ws=list(Ws); bs=list(bs); Ws[5]=W6; bs[5]=b6
    print('L6 units',len(idx))
    return Ws,bs,W7n,b7
